    def nv_image_delete(self, i, ref):
        tagged = i["tag"] != "<none>"
        if not confirm(self.win, "¿Borrar la imagen %s?" % (ref if tagged else i["id"]),
                       "Ocupa %s. Si hace falta, se vuelve a descargar o a preparar." % i["size"],
                       "Borrar la imagen", destructive=True):
